package com.littlemorning.alarm;
import android.app.*;
import android.content.*;
import android.content.res.*;
import android.graphics.*;
import android.graphics.drawable.*;
import android.view.*;
import android.widget.*;

final class Ui {
    static void setText(TextView view,String value){if(!android.text.TextUtils.equals(view.getText(),value))view.setText(value);}
    static int dp(Context c,int n){return (int)(n*c.getResources().getDisplayMetrics().density+.5f);}
    static int color(Context c,int id){return c.getColor(id);}
    static boolean night(Context c){return (c.getResources().getConfiguration().uiMode&Configuration.UI_MODE_NIGHT_MASK)==Configuration.UI_MODE_NIGHT_YES;}
    static GradientDrawable shape(Context c,int color,int radius){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(c,radius));return d;}
    static TextView text(Context c,String value,int size,int role){TextView v=new TextView(c);v.setText(value);v.setTextSize(size);v.setTextColor(color(c,role));v.setTypeface(Typeface.create("sans-serif",Typeface.NORMAL));v.setIncludeFontPadding(false);v.setLineSpacing(dp(c,4),1);return v;}
    static LinearLayout column(Context c){LinearLayout l=new LinearLayout(c);l.setOrientation(LinearLayout.VERTICAL);return l;}
    static LinearLayout row(Context c){LinearLayout l=new LinearLayout(c);l.setGravity(Gravity.CENTER_VERTICAL);return l;}
    static void space(LinearLayout root,int height){View v=new View(root.getContext());root.addView(v,new LinearLayout.LayoutParams(1,dp(root.getContext(),height)));}
    static void line(LinearLayout root){View v=new View(root.getContext());v.setBackgroundColor(color(root.getContext(),R.color.line));root.addView(v,new LinearLayout.LayoutParams(-1,dp(root.getContext(),1)));}
    static void weight(LinearLayout root,View v){root.addView(v,new LinearLayout.LayoutParams(0,-2,1));}
    static void ripple(View view){Context c=view.getContext();view.setBackground(new RippleDrawable(ColorStateList.valueOf((color(c,R.color.accent)&0xFFFFFF)|0x20000000),null,shape(c,Color.WHITE,12)));}
    static Button button(Context c,String title,boolean primary,Runnable click){Button v=new Button(c);v.setAllCaps(false);v.setText(title);v.setTextSize(16);v.setTypeface(Typeface.create("sans-serif-medium",Typeface.NORMAL));v.setTextColor(color(c,primary?R.color.on_accent:R.color.accent));v.setMinHeight(dp(c,56));v.setMinimumHeight(dp(c,56));v.setMinWidth(0);v.setMinimumWidth(0);v.setPadding(dp(c,14),dp(c,14),dp(c,14),dp(c,14));GradientDrawable bg=shape(c,color(c,primary?R.color.accent:R.color.bg),16);if(!primary)bg.setStroke(dp(c,1),color(c,R.color.line));v.setBackground(new RippleDrawable(ColorStateList.valueOf(0x22000000),bg,null));v.setOnClickListener(x->click.run());v.setLayoutParams(new LinearLayout.LayoutParams(-1,-2));return v;}
    static Button quiet(Context c,String title,Runnable click){Button b=button(c,title,false,click);b.setBackgroundColor(Color.TRANSPARENT);b.setMinHeight(dp(c,48));b.setMinimumHeight(dp(c,48));return b;}
    static LinearLayout mount(Activity a){a.getWindow().setStatusBarColor(color(a,R.color.bg));a.getWindow().setNavigationBarColor(color(a,R.color.bg));a.getWindow().getDecorView().setSystemUiVisibility(night(a)?0:View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR|View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR);LinearLayout outer=column(a);outer.setBackgroundColor(color(a,R.color.bg));outer.setPadding(dp(a,24),dp(a,12),dp(a,24),dp(a,20));outer.setOnApplyWindowInsetsListener((v,i)->{outer.setPadding(dp(a,24),i.getSystemWindowInsetTop()+dp(a,8),dp(a,24),i.getSystemWindowInsetBottom()+dp(a,16));return i;});a.setContentView(outer);outer.post(()->{if(android.os.Build.VERSION.SDK_INT>=30&&a.getWindow().getInsetsController()!=null){int flags=WindowInsetsController.APPEARANCE_LIGHT_STATUS_BARS|WindowInsetsController.APPEARANCE_LIGHT_NAVIGATION_BARS;a.getWindow().getInsetsController().setSystemBarsAppearance(night(a)?0:flags,flags);}});return outer;}
    static void header(Activity a,LinearLayout root,String title,Runnable back,String right,Runnable action){LinearLayout bar=row(a);if(back!=null){Button b=quiet(a,"‹",back);b.setTextSize(30);b.setContentDescription("返回");bar.addView(b,new LinearLayout.LayoutParams(dp(a,48),dp(a,56)));}TextView label=text(a,title,18,R.color.ink);label.setTypeface(Typeface.create("sans-serif-medium",0));weight(bar,label);if(right!=null){Button b=quiet(a,right,action);bar.addView(b,new LinearLayout.LayoutParams(-2,-2));}root.addView(bar,new LinearLayout.LayoutParams(-1,-2));space(root,16);}
    static LinearLayout scroll(LinearLayout root){Context c=root.getContext();ScrollView s=new ScrollView(c);s.setFillViewport(true);s.setClipToPadding(false);LinearLayout body=column(c);s.addView(body,new ScrollView.LayoutParams(-1,-2));root.addView(s,new LinearLayout.LayoutParams(-1,0,1));return body;}
    static void title(LinearLayout root,String title,String detail){Context c=root.getContext();TextView t=text(c,title,28,R.color.ink);t.setTypeface(Typeface.create("sans-serif-medium",0));root.addView(t);if(detail!=null){space(root,12);root.addView(text(c,detail,14,R.color.muted));}space(root,28);}
    static void section(LinearLayout root,String title){space(root,24);root.addView(text(root.getContext(),title,14,R.color.muted));space(root,12);}
    static void item(LinearLayout root,String title,String detail,String trailing,Runnable click){Context c=root.getContext();LinearLayout row=row(c);row.setPadding(0,dp(c,18),0,dp(c,18));row.setMinimumHeight(dp(c,72));LinearLayout copy=column(c);copy.addView(text(c,title,16,R.color.ink));if(detail!=null&&!detail.isEmpty()){space(copy,6);copy.addView(text(c,detail,14,R.color.muted));}weight(row,copy);if(trailing!=null){TextView arrow=text(c,trailing,16,R.color.muted);arrow.setPadding(dp(c,12),0,0,0);row.addView(arrow);}if(click!=null){ripple(row);row.setFocusable(true);row.setOnClickListener(v->click.run());}root.addView(row);line(root);}
    static EditText field(LinearLayout root,String hint,String value,boolean multiline){Context c=root.getContext();EditText field=new EditText(c);field.setText(value);field.setHint(hint);field.setTextSize(16);field.setTextColor(color(c,R.color.ink));field.setHintTextColor(color(c,R.color.muted));field.setSingleLine(!multiline);field.setMinLines(multiline?4:1);field.setGravity(Gravity.TOP|Gravity.START);field.setPadding(dp(c,12),dp(c,16),dp(c,12),dp(c,16));field.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(multiline?500:30)});root.addView(field,new LinearLayout.LayoutParams(-1,-2));return field;}
    static void note(LinearLayout root,String text){Context c=root.getContext();TextView n=text(c,text,14,R.color.muted);n.setPadding(dp(c,16),dp(c,16),dp(c,16),dp(c,16));n.setBackground(shape(c,color(c,R.color.surface),12));root.addView(n,new LinearLayout.LayoutParams(-1,-2));}
}
